WITH cleaned AS (SELECT *, LENGTH(status) AS status_length, CONCAT_WS(',', status, plan) AS status_plan_key FROM subscriptions WHERE start_date > DATE '2023-05-20' AND end_date >= '2025-06-01'), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, customer_id ORDER BY status_length DESC NULLS LAST, id) AS rn FROM cleaned QUALIFY rn = 1), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY monthly_fee, id) AS dedup_rank FROM latest) x WHERE dedup_rank = 1), metrics AS (SELECT *, MIN(status_length) OVER (PARTITION BY status ORDER BY rn, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_status_length, AVG(status_length) OVER (PARTITION BY status ORDER BY rn, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_status_length, COUNT(status_length) OVER (PARTITION BY status ORDER BY rn, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_status_length, SUM(status_length) OVER (PARTITION BY status ORDER BY rn, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_status_length, NTILE(10) OVER (PARTITION BY status ORDER BY monthly_fee, id) AS monthly_fee_bucket FROM ranked), with_dims AS (SELECT s.*, c.country FROM metrics s LEFT JOIN customers c ON s.customer_id <=> c.id) SELECT p.country AS customer_country, a.country AS subscription_country, COUNT(*) AS cnt, MIN(a.status_length) AS min_status_length, GROUPING_ID() AS grouping_level FROM with_dims a LEFT JOIN customers p ON a.customer_id = p.id GROUP BY CUBE (p.country, a.country)
